//! AC-L1: every implemented rule has 3 positive and 3 negative fixtures (`tests/fixtures/lint/<rule>/`).
//! Fixtures are generated by `tests/fixtures/lint/gen.py` (synthetic art only).

use agentsprite::lint::{self, LintOpts, Severity, SPRITE_RULES};
use agentsprite::{profile, pxl, template};
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/lint")
}

fn run_case(rule: &str, file: &Path) -> Vec<lint::Issue> {
    let part = pxl::load(file).unwrap();
    let pf = file.with_extension("profile.toml");
    let prof = if pf.is_file() { profile::load(pf.to_str().unwrap()).unwrap() } else { profile::load("gbc-sprite").unwrap() };
    let opts = LintOpts { rules: vec![rule.to_string()], frames: vec![], refs: true, advice: false };
    let tpl_res = template::load_for(&part);
    let all = match &tpl_res {
        Ok(t) => lint::lint_part(&part, t, &prof, &opts),
        Err(_) => lint::lint_part_auto(&part, &prof, &opts),
    };
    all.into_iter().filter(|i| i.rule == rule).collect()
}

#[test]
fn every_rule_has_three_positive_and_three_negative_fixtures() {
    let mut checked = 0;
    for rule in SPRITE_RULES.iter().filter(|r| **r != "template") .chain(["template"].iter()) {
        let dir = root().join(rule);
        for kind in ["pos", "neg"] {
            for n in 1..=3 {
                let f = dir.join(format!("{}{}.pxl", kind, n));
                assert!(f.is_file(), "missing fixture {}", f.display());
                let issues = run_case(rule, &f);
                if kind == "pos" {
                    assert!(!issues.is_empty(), "{} should trigger rule {}", f.display(), rule);
                } else {
                    assert!(issues.is_empty(), "{} should not trigger rule {}: {:?}", f.display(), rule, issues);
                }
                checked += 1;
            }
        }
    }
    assert_eq!(checked, SPRITE_RULES.len() * 6);
}

#[test]
fn family_template_fixtures() {
    for (case, expect) in [("pos1", true), ("pos2", true), ("pos3", true), ("neg1", false), ("neg2", false), ("neg3", false)] {
        let dir = root().join("family").join(case);
        let mut parts = Vec::new();
        let mut files: Vec<_> = std::fs::read_dir(&dir).unwrap().flatten().map(|e| e.path()).filter(|p| p.extension().map_or(false, |x| x == "pxl")).collect();
        files.sort();
        for f in files {
            parts.push(pxl::load(&f).unwrap());
        }
        let refs: Vec<&_> = parts.iter().collect();
        let issues = lint::family_issues(&refs);
        assert_eq!(!issues.is_empty(), expect, "family {}: {:?}", case, issues);
        assert!(issues.iter().all(|i| i.rule == "template" && i.severity == Severity::Error));
    }
}

#[test]
fn issues_are_ordered_and_deterministic() {
    let f = root().join("hw_cells/pos1.pxl");
    let part = pxl::load(&f).unwrap();
    let prof = profile::load("gbc-sprite").unwrap();
    let a = lint::lint_part_auto(&part, &prof, &LintOpts::default());
    let b = lint::lint_part_auto(&part, &prof, &LintOpts::default());
    assert_eq!(a, b);
    let ys: Vec<i32> = a.iter().map(|i| i.y.unwrap_or(-1)).collect();
    let mut s = ys.clone();
    s.sort();
    assert_eq!(ys, s);
}

#[test]
fn size_rule_on_mismatching_grid() {
    let mut part = pxl::load(&root().join("size/neg2.pxl")).unwrap();
    part.frames[0].grid = agentsprite::model::Grid::new(15, 16, b'.');
    let prof = profile::load("gbc-sprite").unwrap();
    let tpl = template::load_for(&part).unwrap();
    let issues = lint::lint_part(&part, &tpl, &prof, &LintOpts { rules: vec!["size".into()], ..Default::default() });
    assert_eq!(issues.len(), 1);
}

#[test]
fn fixes_are_ready_to_run_commands() {
    let part = pxl::load(&root().join("orphan/pos1.pxl")).unwrap();
    let prof = profile::load("gbc-sprite").unwrap();
    let tpl = template::load_for(&part).unwrap();
    let issues = lint::lint_part(&part, &tpl, &prof, &LintOpts { rules: vec!["orphan".into()], ..Default::default() });
    let fix = issues[0].fix.clone().unwrap();
    assert!(fix.starts_with("pxl set ") && fix.ends_with(" 14,14=."), "{}", fix);
    let part = pxl::load(&root().join("jaggy/pos1.pxl")).unwrap();
    let issues = lint::lint_part(&part, &tpl, &prof, &LintOpts { rules: vec!["jaggy".into()], ..Default::default() });
    assert!(issues.iter().all(|i| i.fix.as_deref().map_or(false, |f| f.starts_with("pxl set "))));
}

#[test]
fn profiles_load() {
    let s = profile::load("gbc-sprite").unwrap();
    assert_eq!((s.colors, s.hw_cell, s.hw_cells_warn, s.hw_cells_per_row_warn, s.channel_step), (3, (8, 16), 12, 5, 8));
    assert_eq!((s.hw_cells_per_row_max, s.hw_cells_max), (10, 40));
    let t = profile::load("gbc-tile").unwrap();
    assert_eq!((t.colors_per_tile, t.palettes, t.transparent, t.unique_tiles_max, t.sheet_width), (4, 8, false, 348, 128));
    assert_eq!(profile::load("gbc-screen").unwrap().size, Some((160, 144)));
    assert!(profile::load("nope").is_err());
}

#[test]
fn hw_overlay_counts_as_separate_sprites() {
    let prof = profile::load("gbc-sprite").unwrap();
    for (rel, rule, expect, msg) in [
        ("hw_cells/pos4.pxl", "hw_cells", true, "6 hardware sprites side by side in the 16 px band at y=0 (5 base + 1 overlay)"),
        ("hw_cells/neg4.pxl", "hw_cells", false, ""),
        ("hw_limit/pos4.pxl", "hw_limit", true, "12 sprite cells in the 16 px band at y=0 (6 base + 6 overlay)"),
        ("hw_limit/neg4.pxl", "hw_limit", false, ""),
    ] {
        let part = pxl::load(&root().join(rel)).unwrap();
        let tpl = template::load_for(&part).unwrap();
        let issues = lint::lint_part(&part, &tpl, &prof, &LintOpts { rules: vec![rule.into()], ..Default::default() });
        assert_eq!(!issues.is_empty(), expect, "{}: {:?}", rel, issues);
        if expect {
            assert!(issues.iter().any(|i| i.message.contains(msg)), "{}: {:?}", rel, issues);
        }
    }
}
